  "ui.wpAdminAgentFrameApp.feedback103": "Поточний контекст адміністратора WordPress не дозволяє читання вибраного об’єкта {value1}. Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback104": "Не вдалося знову підтвердити доступ до явно вибраного запису WordPress {value1}. Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback105": "Не вдалося повністю завантажити поточний документ Gutenberg ({value1}). Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback106": "Поточний документ Gutenberg доступний лише як прив’язаний знімок, розбитий на частини. Не можна підготувати зміну всього документа, доки не прочитано всі необхідні частини. Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback107": "У поточному записі Gutenberg є незбережені зміни. Збережіть або оновіть його, перш ніж Pixflow прочитає його чи підготує правку з урахуванням вмісту. Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback108": "Видалення всіх блоків Gutenberg зараз не підтримується. Pixflow не трактував запит як заміну порожнім вмістом. Нічого не змінено.",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow не зміг визначити, чи відповідає повідомлення на очікуване уточнення, чи починає новий запит. Перевірку не підготовлено, нічого не змінено.",
  "ui.wpAdminAgentFrameApp.feedback110": "Поточний документ Gutenberg розбито на частини й прочитано не повністю, тому Pixflow не може підготувати перевірку всього документа. Я нічого не змінив.",
  "ui.wpAdminAgentFrameApp.feedback111": "Повну заміну Gutenberg не було явно запитано, тому Pixflow відмовився замінювати поточний документ. Нічого не змінено.",
  "ui.wpAdminAgentFrameApp.feedback112": "Pixflow не зміг оновити повноваження для об’єкта WordPress після попередньої дії. Попередні дії буде скасовано.",
  "ui.wpAdminAgentFrameApp.feedback113": "Необхідний запис не було створено з коректним ID WordPress. Попередні дії буде скасовано.",
