  "wp.message.26a6374fbf59": "Не вдалося запустити доповнення Pixflow. Перевірте сумісність плагінів Pixflow і перезавантажте сторінку. Інші функції можуть залишатися доступними.",
  "wp.message.ca7714cffbcc": "Активувати Pro",
  "wp.message.197c83a2f752": "Поверніть розширені інструменти з доповненням Pro. Ліцензія, вміст і збережені налаштування залишаться на місці. Якщо ви використовували двофакторну автентифікацію Bricks, увімкніть її знову в налаштуваннях після активації Pro.",
  "wp.message.2ffdcbc380ea": "Створюйте в улюбленому конструкторі. Додайте до своєї роботи анотації, голос, дизайн-системи та генерування зображень.",
  "wp.message.40ed1102964b": "Перевірити пробний період Pro",
  "wp.message.e9cccd3ef5fc": "Не вдалося зберегти закриття сповіщення. Спробуйте ще раз.",
  "wp.message.1372089fb797": "Закрити банер Pixflow Pro",
  "wp.message.5e3ba715018d": "Завантажити Pro",
  "wp.message.fb2e6d87b44c": "Більше можливостей із Pixflow Design Pro",
  "wp.message.9934717ca744": "Оновіть сторінку та спробуйте ще раз.",
  "wp.message.7c78f9990490": "Почати 7-денний пробний період Pro",
  "wp.message.f89b4dcf2c2e": "Спробувати Pro протягом 7 днів",
  "wp.message.69ecce9deb2d": "Ви не можете закрити це сповіщення.",
  "wp.message.927384e7eed8": "Ваш тариф Pixflow містить Pro",
  "wp.message.64585a3a39ef": "[%s] Двофакторну автентифікацію скинуто",
  "wp.message.97c3ac935cc2": "[%s] Ваш код підтвердження",
  "wp.message.b075b6e113fc": "10 хвилин",
  "wp.message.8bbe8944007a": "Двофакторна автентифікація",
  "wp.message.c2bf03beb4f6": "Налаштування двофакторної автентифікації",
  "wp.message.3170543ce47c": "5 хвилин",
  "wp.message.0d1fa0dfcc9e": "6-значний код",
  "wp.message.8b6693be283d": "Панель облікового запису",
  "wp.message.107a3671eb84": "Колір активного/завершеного стану",
  "wp.message.47d932f4c02a": "Колір номера активного/завершеного кроку",
  "wp.message.73dbcf028ec6": "Додайте другий спосіб підтвердження для захисту облікового запису.",
  "wp.message.529da8588051": "Для завершення входу потрібне додаткове підтвердження.",
  "wp.message.6b49000156c3": "Адміністратори можуть використати це аварійне скидання, якщо користувач утратив усі засоби автентифікації та коди відновлення.",
  "wp.message.4ea44caf5d6e": "Після форми",
  "wp.message.1be05927766c": "Адміністратор вимкнув двофакторну автентифікацію для вашого облікового запису. Якщо ви не очікували цієї зміни, скиньте пароль і негайно зверніться до адміністратора сайту.",
  "wp.message.bd4a7c92a53f": "Вікно автентифікації/пошти/ключа доступу",
  "wp.message.09a12ace273f": "Застосунок-автентифікатор",
  "wp.message.a4c801f3d189": "Застосунок-автентифікатор готовий",
  "wp.message.9fd5a3f4f23e": "Налаштування застосунку-автентифікатора вимкнено для цього сайту.",
  "wp.message.7258165188b4": "Опис автентифікатора",
  "wp.message.7cb96fa5a704": "Попередній перегляд QR-коду автентифікатора",
  "wp.message.838557924a5c": "Резервна копія",
  "wp.message.216f00eada6a": "Перед формою",
  "wp.message.9e2b8fcf9a19": "Заповнювач заблокованого вмісту",
  "wp.message.745c19fce0bf": "Заповнювач заблокованого вмісту",
  "wp.message.de4aeff9ee43": "Типографіка основного тексту",
  "wp.message.45e9870097b1": "Лише в конструкторі. Закріпіть вибраний попередній перегляд відкритим під час оформлення інших елементів.",
  "wp.message.c3d4759d35d0": "Попередній перегляд у конструкторі",
  "wp.message.5be164b5cb70": "Не вдається відсканувати? Введіть цей ключ налаштування вручну:",
  "wp.message.91cfaf3e7a2c": "Скасувати й повернутися",
  "wp.message.3b72859f271e": "Текст кнопки скасування",
  "wp.message.739dee74b4dc": "По центру",
  "wp.message.fd00836aed08": "Завершіть налаштування двофакторної автентифікації, щоб продовжити.",
