  "wp.message.66d7671d170d": "Установіть останню версію Google Site Kit і налаштуйте сервіс входу через Google в розділі:",
  "wp.message.793e6000d1b8": "Потрібна інтерактивна двофакторна автентифікація; для доступу до API використовуйте пароль застосунку WordPress.",
