  "wp.message.594d0d476015": "Ключі доступу та ключі безпеки",
  "wp.message.56da94bc376c": "Для ключів доступу потрібні HTTPS і розширення PHP OpenSSL та mbstring.",
  "wp.message.1d3f35031a5a": "Власний код Splide у Pixflow",
  "wp.message.b73a688afd1a": "Pixflow Design Pro потребує сумісну збірку основного Pixflow Design. Оновіть обидва плагіни разом.",
  "wp.message.7ecf123f8f20": "Для Pixflow Design Pro має бути активним основний плагін Pixflow Design.",
  "wp.message.46d86360f524": "Двофакторна автентифікація Pixflow",
  "wp.message.e70f8f3b8315": "Розмістіть цей елемент один раз у загальному шаблоні підвалу Bricks. Сервіси згоди, виявлення та блокування налаштовуються в Pixflow Design → Розширення Bricks → Згода на cookie.",
