  "wp.message.22ba7abac520": "Опис відновлення",
  "wp.message.c7901fa498bb": "Текст кнопки надсилання відновлення",
  "wp.message.2374561a7b97": "Видалити всі зареєстровані способи, ключі доступу та коди відновлення.",
  "wp.message.77bbc9ed8bef": "Показати підключену кнопку входу через Google з Google Site Kit у цій формі.",
  "wp.message.858bbbd0f6e8": "Повторне надсилання через 1:00",
  "wp.message.01c88bb1a49f": "Скинути двофакторну автентифікацію",
  "wp.message.e569a7dd5f6d": "Скинути всю двофакторну автентифікацію",
  "wp.message.5362713d638e": "Кнопка скидання",
  "wp.message.0b443363f14e": "Збережіть ці одноразові коди відновлення в безпечному місці. Вони показуються лише один раз.",
  "wp.message.76e07d866ee3": "Відскануйте цей QR-код застосунком-автентифікатором, потім підтвердьте шестизначний код.",
  "wp.message.62f2ccfffcc5": "Вторинний",
  "wp.message.193a98699d02": "Захистіть обліковий запис",
  "wp.message.753a970dd23f": "Захистіть обліковий запис, перш ніж WordPress завершить цей вхід.",
