  "wp.message.d8d92d22f721": "Надіслати код електронною поштою",
  "wp.message.19e86d2b7055": "Надіслати код підтвердження",
  "wp.message.4da10f1fbb17": "Налаштувати",
  "wp.message.b5037bab5a4a": "Налаштувати ключ доступу",
  "wp.message.b7522cb65e91": "Налаштуйте застосунок-автентифікатор, коди електронною поштою або ключ доступу перед створенням кодів відновлення.",
