  "wp.message.41af78359ce6": "Типографіка тексту",
  "wp.message.b68943b35209": "Підтвердження не прийнято. Спробуйте ще раз.",
  "wp.message.1f0ec82c0aa3": "Обліковий запис більше не існує.",
