  "wp.message.b0f196cf2a59": "Використайте автентифікатор, код із листа, ключ доступу або код відновлення для завершення входу.",
  "wp.message.8e9144afb01c": "Спосіб підтвердження",
  "wp.message.cc4d85614069": "Код підтвердження або відновлення",
