  "wp.message.7a970cb4533f": "Підтвердити й увійти",
  "wp.message.4d8f4755ac09": "Підтвердьте свою особу",
  "wp.message.2fcac134b4c3": "Підтвердьте застосунок-автентифікатор",
  "wp.message.428defb7b530": "Підтвердьте код із листа",
  "wp.message.e981ddae45d8": "Попередження",
  "wp.message.41298e82bbe5": "Ми надішлемо код підтвердження з коротким терміном дії на i•••@example.com.",
